var arRec AmtRec

func wrapDecimal(d decimal.Decimal, intDigits int32, scale int32) decimal.Decimal {
	tr := d.Truncate(scale)
	// scaled integer = tr * 10^scale
	scaled := tr.Shift(scale).Truncate(0)
	modPow := int32(intDigits + scale)
	mod := decimal.NewFromInt(1).Shift(modPow) // 10^(int+scale)
	// positive mod
	// scaled may be negative: need Euclidean mod for COBOL? For positive values simple.
	// Use Mod
	rem := scaled.Mod(mod)
	if rem.IsNegative() {
		rem = rem.Add(mod)
	}
	return rem.Shift(-scale)
}

func fitsInPic(d decimal.Decimal, intDigits int32, scale int32) bool {
	tr := d.Truncate(scale)
	// check absolute value < 10^intDigits
	limit := decimal.NewFromInt(1).Shift(intDigits) // 10^intDigits
	// integer part absolute
	// truncate divides scale already
	// Get absolute value of truncated
	abs := tr.Abs()
	// Compare abs < limit (since max is 10^intDigits - 10^-scale)
	// overflow if abs >= limit
	if abs.Cmp(limit) >= 0 {
		return false
	}
	return true
}

func addWithSizeError(target *decimal.Decimal, addVal decimal.Decimal, intDigits int32, scale int32, onError func()) {
	sum := target.Add(addVal).Truncate(scale)
	if !fitsInPic(sum, intDigits, scale) {
		// size error: leave target unchanged
		onError()
		return
	}
	*target = sum
}

