	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// Pad leading zeros to intSlots width for mapping
	padded := strings.Repeat("0", intSlots-len(intStr)) + intStr

	// Map padded digits to intPic placeholders
	// We need to know for each placeholder position its digit
