		} else if ch == ',' {
			if suppress {
				// check if all remaining Z/digits up to this point were suppressed?
				// Commas inside suppressed zone become spaces
				// Determine if still suppressing (i.e., all previous Z digits were zero-spaces)
				// The suppress flag already indicates we are still in leading zero zone
				// But need to look ahead: if suppression still active, comma -> space
				intResult[i] = ' '
