func parseAmt(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s contains digits only, length 7, implied 2 decimals
	// may contain spaces? trim already
	n := decimal.RequireFromString(s)
	return n.Shift(-2)
}

func MAINPARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		f, _ = os.Open("input.dat")
		if err != nil {
			// if file not exists, treat as empty
			// still need summary
			SUMMARYPARA()
			return
		}
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// COBOL LINE SEQUENTIAL keeps lines without newline; scanner handles
	var records []string
	for scanner.Scan() {
		line := scanner.Text()
		records = append(records, line)
	}
	idx := 0
	readFunc := func() {
		if idx >= len(records) {
			WsEofFlag = "Y"
			return
		}
		line := records[idx]
		idx++
		// pad to 11
		if len(line) < 11 {
			line = line + strings.Repeat(" ", 11-len(line))
		}
		if len(line) > 11 {
			line = line[:11]
		}
		arRec.ArAcct = line[0:4]
		amtStr := line[4:11]
		arRec.ArAmt = parseAmt(amtStr)
		WsEofFlag = "N"
	}
	// PERFORM READ-PARA
	readFunc()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for WsEofFlag != "Y" {
		PROCESSPARA(readFunc)
	}
	SUMMARYPARA()
}

func PROCESSPARA(readFunc func()) {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = WsBigTotal.Add(arRec.ArAmt).Truncate(2)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL (wrap high digits)
	WsWrapTotal = wrapDecimal(WsBigTotal, 5, 2)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	addWithSizeError(&WsSafeTotal, arRec.ArAmt, 5, 2, func() {
		OVERFLOWPARA()
	})
	// ADD 1 TO WS-COUNT
	WsCount++
	// COMPUTE WS-HALF = AR-AMT / 2  (truncated to 1 decimal)
	// Use decimal divide then truncate
	WsHalf = arRec.ArAmt.Div(decimal.NewFromInt(2)).Truncate(1)
	// MOVE to edited
	WsAmtEd = formatEdited(arRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
	fmt.Printf("%s %s %s %s %s\n", arRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	readFunc()
}

func SUMMARYPARA() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func OVERFLOWPARA() {
	WsOverflows++
}

func main() {
	MAINPARA()
}

